(606,1260,'DEF: P. falciparum malaria in new born transmitted directly from the mother. DESC: Placental involvement by the malarial parasite may lead to spontaneous abortion, stillbirth, or, rarely, congenital infection. REF: Merck','en',2,'2026-03-05 23:42:05',NULL,NULL,'13647FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(607,1261,'Congenital malformations of organs or parts.','en',2,'2026-03-05 23:42:05',NULL,NULL,'13646FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
